export type MediaType = 'movie' | 'tv' | 'anime';

export interface CastMember {
  id: string;
  name: string;
  character?: string;
  profilePath?: string;
}

export interface MediaItem {
  id: string;
  tmdbId?: number;
  imdbId?: string;
  title: string;
  overview: string;
  posterPath: string;
  backdropPath: string;
  mediaType: MediaType;
  genres: string[];
  cast: CastMember[];
  runtime?: number;
  rating: number;
  voteCount?: number;
  releaseDate?: string;
  year?: number;
}

export interface ContinueWatchingItem {
  media: MediaItem;
  progress: number;
  duration: number;
  updatedAt: number;
}

export interface WatchHistoryEntry {
  media: MediaItem;
  watchedAt: number;
  progress: number;
}

export interface PlaybackSettings {
  preferredProviderId: string;
  volume: number;
  autoplay: boolean;
  subtitles: string;
}

export type SearchFilterType = 'all' | 'movie' | 'tv';

export interface SearchFilters {
  type: SearchFilterType;
  genre: string;
  year: string;
  minRating: number;
}

const PREFIX = 'streamforge:';

export function readStorage<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(`${PREFIX}${key}`);
    if (!raw) return fallback;
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

export function writeStorage<T>(key: string, value: T): void {
  try {
    localStorage.setItem(`${PREFIX}${key}`, JSON.stringify(value));
  } catch {
    // quota exceeded — silently fail
  }
}

export const STORAGE_KEYS = {
  favorites: 'favorites',
  history: 'history',
  continueWatching: 'continue-watching',
  playback: 'playback-settings',
  provider: 'preferred-provider',
} as const;

export function formatRuntime(minutes?: number): string {
  if (!minutes) return '—';
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  if (h === 0) return `${m}m`;
  return m > 0 ? `${h}h ${m}m` : `${h}h`;
}

export function formatRating(rating: number): string {
  if (!rating) return 'N/A';
  return rating.toFixed(1);
}

export function formatYear(date?: string, year?: number): string {
  if (year) return String(year);
  if (!date) return '—';
  return date.slice(0, 4);
}

export function truncate(text: string, max: number): string {
  if (text.length <= max) return text;
  return `${text.slice(0, max).trim()}…`;
}

export function slugMediaId(id: string): string {
  return id.replace(/^tt/, '');
}

export function debounce<T extends (...args: Parameters<T>) => void>(
  fn: T,
  delay: number,
): (...args: Parameters<T>) => void {
  let timer: ReturnType<typeof setTimeout>;
  return (...args: Parameters<T>) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const TMDB_BASE = 'https://image.tmdb.org/t/p';

export function tmdbImage(
  path: string | null | undefined,
  size: 'w342' | 'w500' | 'w780' | 'original' = 'w500',
): string {
  if (!path) return '/placeholder-poster.svg';
  if (path.startsWith('http')) return path;
  return `${TMDB_BASE}/${size}${path}`;
}

export function backdropImage(path?: string): string {
  return tmdbImage(path, 'w780');
}

export function posterImage(path?: string): string {
  return tmdbImage(path, 'w500');
}

import type { MediaType } from '@/types/media';

export interface ProviderContext {
  mediaId: string;
  mediaType: MediaType;
  season?: number;
  episode?: number;
  startAt?: number;
  autoplay?: boolean;
}

export interface Provider {
  id: string;
  name: string;
  quality: string;
  description: string;
  getPlaybackSource: (ctx: ProviderContext) => string;
}

import type { Provider } from './Provider';
import { buildVidcoreUrl } from './vidcore';

export const primaryProvider: Provider = {
  id: 'primary',
  name: 'Primary',
  quality: 'HD',
  description: 'Fast',
  getPlaybackSource: (ctx) =>
    buildVidcoreUrl(ctx, { server: 'primary', qualityLabel: 'hd' }),
};

import type { Provider } from './Provider';
import { buildVidcoreUrl } from './vidcore';

export const backupProvider: Provider = {
  id: 'backup',
  name: 'Backup',
  quality: 'Ultra',
  description: 'Fallback stream',
  getPlaybackSource: (ctx) =>
    buildVidcoreUrl(ctx, { server: 'backup', qualityLabel: 'ultra' }),
};

import type { ProviderContext } from './Provider';

const BASE = 'https://vidcore.net';

function normalizeId(mediaId: string): string {
  const trimmed = mediaId.trim();
  if (trimmed.startsWith('tt')) return trimmed;
  if (/^\d+$/.test(trimmed)) return trimmed;
  return trimmed;
}

interface VidcoreOptions {
  server?: string;
  qualityLabel?: string;
}

export function buildVidcoreUrl(
  ctx: ProviderContext,
  options: VidcoreOptions = {},
): string {
  const id = normalizeId(ctx.mediaId);
  const isTv = ctx.mediaType === 'tv' || ctx.mediaType === 'anime';
  const path = isTv ? 'tv' : 'movie';
  const url = new URL(`${BASE}/${path}/${id}`);

  url.searchParams.set('autoPlay', String(ctx.autoplay ?? true));
  url.searchParams.set('title', 'false');
  url.searchParams.set('poster', 'false');

  if (options.server) {
    url.searchParams.set('server', options.server);
  }

  if (ctx.startAt && ctx.startAt > 0) {
    url.searchParams.set('startAt', String(Math.floor(ctx.startAt)));
  }

  if (isTv && ctx.season != null && ctx.episode != null) {
    url.searchParams.set('season', String(ctx.season));
    url.searchParams.set('episode', String(ctx.episode));
  }

  return url.toString();
}

import { readStorage, writeStorage, STORAGE_KEYS } from '@/utils/storage';
import type { Provider, ProviderContext } from './Provider';
import { primaryProvider } from './primary';
import { backupProvider } from './backup';

const providers: Provider[] = [primaryProvider, backupProvider];

let activeProviderId = readStorage<string>(
  STORAGE_KEYS.provider,
  primaryProvider.id,
);

export function getProviders(): Provider[] {
  return providers;
}

export function getActiveProvider(): Provider {
  return (
    providers.find((p) => p.id === activeProviderId) ?? primaryProvider
  );
}

export function getProviderById(id: string): Provider | undefined {
  return providers.find((p) => p.id === id);
}

export function switchProvider(id: string): Provider {
  const next = getProviderById(id);
  if (!next) {
    return getActiveProvider();
  }
  activeProviderId = next.id;
  writeStorage(STORAGE_KEYS.provider, next.id);
  return next;
}

export function getPlaybackSource(ctx: ProviderContext): string {
  return getActiveProvider().getPlaybackSource(ctx);
}

export function getPlaybackSourceWithFallback(
  ctx: ProviderContext,
): { source: string; provider: Provider } {
  const active = getActiveProvider();
  return { source: active.getPlaybackSource(ctx), provider: active };
}

export function tryFallbackProvider(
  currentId: string,
): Provider | null {
  const fallback = providers.find((p) => p.id !== currentId);
  if (!fallback) return null;
  return switchProvider(fallback.id);
}

const API_KEY = import.meta.env.VITE_TMDB_API_KEY as string | undefined;
const BASE = 'https://api.themoviedb.org/3';

export function hasTmdbKey(): boolean {
  return Boolean(API_KEY && API_KEY !== 'your_tmdb_api_key_here');
}

async function tmdbFetch<T>(path: string, params: Record<string, string> = {}): Promise<T> {
  if (!hasTmdbKey()) {
    throw new Error('TMDB API key not configured');
  }
  const url = new URL(`${BASE}${path}`);
  url.searchParams.set('api_key', API_KEY!);
  Object.entries(params).forEach(([k, v]) => url.searchParams.set(k, v));
  const res = await fetch(url.toString());
  if (!res.ok) throw new Error(`TMDB error: ${res.status}`);
  return res.json() as Promise<T>;
}

export { tmdbFetch, API_KEY };

const BASE = 'https://v3-cinemeta.strem.io';

interface CinemetaMeta {
  id: string;
  type: string;
  name: string;
  poster?: string;
  background?: string;
  description?: string;
  genre?: string[];
  imdbRating?: string;
  runtime?: string;
  releaseInfo?: string;
  cast?: string[];
  director?: string[];
}

interface CinemetaCatalog {
  metas: CinemetaMeta[];
}

export async function cinemetaCatalog(
  type: 'movie' | 'series',
  catalog: string,
): Promise<CinemetaMeta[]> {
  const res = await fetch(`${BASE}/catalog/${type}/${catalog}/json`);
  if (!res.ok) return [];
  const data = (await res.json()) as CinemetaCatalog;
  return data.metas ?? [];
}

export async function cinemetaMeta(
  type: 'movie' | 'series',
  id: string,
): Promise<CinemetaMeta | null> {
  const res = await fetch(`${BASE}/meta/${type}/${id}.json`);
  if (!res.ok) return null;
  const data = (await res.json()) as { meta: CinemetaMeta };
  return data.meta ?? null;
}

export async function cinemetaSearch(
  query: string,
  type: 'movie' | 'series' = 'movie',
): Promise<CinemetaMeta[]> {
  const encoded = encodeURIComponent(query);
  const res = await fetch(
    `${BASE}/catalog/${type}/top/search=${encoded}.json`,
  );
  if (!res.ok) return [];
  const data = (await res.json()) as CinemetaCatalog;
  return data.metas ?? [];
}

export type { CinemetaMeta };

import type { CastMember, MediaItem, MediaType } from '@/types/media';
import { hasTmdbKey, tmdbFetch } from './tmdb';
import { cinemetaCatalog, cinemetaMeta, type CinemetaMeta } from './cinemeta';

interface TmdbResult {
  id: number;
  title?: string;
  name?: string;
  overview: string;
  poster_path: string | null;
  backdrop_path: string | null;
  genre_ids?: number[];
  vote_average: number;
  vote_count?: number;
  release_date?: string;
  first_air_date?: string;
  media_type?: string;
}

interface TmdbListResponse {
  results: TmdbResult[];
  page: number;
  total_pages: number;
}

interface TmdbDetail extends TmdbResult {
  genres: { id: number; name: string }[];
  runtime?: number;
  episode_run_time?: number[];
  credits?: {
    cast: { id: number; name: string; character: string; profile_path: string | null }[];
  };
  imdb_id?: string;
}

interface TmdbGenre {
  id: number;
  name: string;
}

const GENRE_CACHE: Partial<Record<MediaType, Map<number, string>>> = {};

function mapTmdbType(type: MediaType): 'movie' | 'tv' {
  return type === 'tv' || type === 'anime' ? 'tv' : 'movie';
}

function inferMediaType(item: TmdbResult, fallback: MediaType): MediaType {
  if (item.media_type === 'tv') return 'tv';
  if (fallback === 'anime') return 'anime';
  return fallback;
}

function mapTmdbItem(item: TmdbResult, type: MediaType, genres: string[] = []): MediaItem {
  const mediaType = inferMediaType(item, type);
  return {
    id: String(item.id),
    tmdbId: item.id,
    title: item.title ?? item.name ?? 'Untitled',
    overview: item.overview ?? '',
    posterPath: item.poster_path ?? '',
    backdropPath: item.backdrop_path ?? '',
    mediaType,
    genres,
    cast: [],
    runtime: item.media_type === 'tv' ? undefined : undefined,
    rating: item.vote_average ?? 0,
    voteCount: item.vote_count,
    releaseDate: item.release_date ?? item.first_air_date,
    year: Number((item.release_date ?? item.first_air_date ?? '').slice(0, 4)) || undefined,
  };
}

function mapCinemetaItem(meta: CinemetaMeta, type: MediaType): MediaItem {
  const runtimeMatch = meta.runtime?.match(/(\d+)/);
  return {
    id: meta.id.replace('tt', '') === meta.id ? meta.id : meta.id,
    imdbId: meta.id.startsWith('tt') ? meta.id : undefined,
    title: meta.name,
    overview: meta.description ?? '',
    posterPath: meta.poster ?? '',
    backdropPath: meta.background ?? meta.poster ?? '',
    mediaType: type === 'anime' ? 'anime' : meta.type === 'series' ? 'tv' : 'movie',
    genres: meta.genre ?? [],
    cast: (meta.cast ?? []).slice(0, 8).map((name, i) => ({
      id: `cast-${i}`,
      name,
    })),
    runtime: runtimeMatch ? Number(runtimeMatch[1]) : undefined,
    rating: Number(meta.imdbRating) || 0,
    releaseDate: meta.releaseInfo,
    year: Number(meta.releaseInfo?.slice(0, 4)) || undefined,
  };
}

async function loadGenres(type: MediaType): Promise<Map<number, string>> {
  if (GENRE_CACHE[type]) return GENRE_CACHE[type]!;
  if (!hasTmdbKey()) return new Map();
  const endpoint = type === 'movie' ? '/genre/movie/list' : '/genre/tv/list';
  const data = await tmdbFetch<{ genres: TmdbGenre[] }>(endpoint);
  const map = new Map(data.genres.map((g) => [g.id, g.name]));
  GENRE_CACHE[type] = map;
  return map;
}

async function enrichWithGenres(items: TmdbResult[], type: MediaType): Promise<MediaItem[]> {
  const genreMap = await loadGenres(type);
  return items.map((item) => {
    const genres = (item.genre_ids ?? [])
      .map((id) => genreMap.get(id))
      .filter(Boolean) as string[];
    return mapTmdbItem(item, type, genres);
  });
}

export async function fetchTrending(type: MediaType = 'movie', page = 1): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const tmdbType = mapTmdbType(type);
    const data = await tmdbFetch<TmdbListResponse>(`/trending/${tmdbType}/week`, {
      page: String(page),
    });
    return enrichWithGenres(data.results, type);
  }
  const catalog = await cinemetaCatalog(
    type === 'movie' ? 'movie' : 'series',
    'top',
  );
  return catalog.slice((page - 1) * 20, page * 20).map((m) =>
    mapCinemetaItem(m, type),
  );
}

export async function fetchPopularMovies(page = 1): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const data = await tmdbFetch<TmdbListResponse>('/movie/popular', {
      page: String(page),
    });
    return enrichWithGenres(data.results, 'movie');
  }
  return cinemetaCatalog('movie', 'top').then((items) =>
    items.slice((page - 1) * 20, page * 20).map((m) => mapCinemetaItem(m, 'movie')),
  );
}

export async function fetchPopularTv(page = 1): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const data = await tmdbFetch<TmdbListResponse>('/tv/popular', { page: String(page) });
    return enrichWithGenres(data.results, 'tv');
  }
  return cinemetaCatalog('series', 'top').then((items) =>
    items.slice((page - 1) * 20, page * 20).map((m) => mapCinemetaItem(m, 'tv')),
  );
}

export async function fetchTopRated(type: MediaType, page = 1): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const endpoint = type === 'movie' ? '/movie/top_rated' : '/tv/top_rated';
    const data = await tmdbFetch<TmdbListResponse>(endpoint, { page: String(page) });
    return enrichWithGenres(data.results, type);
  }
  return fetchTrending(type, page);
}

export async function fetchAnime(page = 1): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const data = await tmdbFetch<TmdbListResponse>('/discover/tv', {
      page: String(page),
      with_genres: '16',
      with_original_language: 'ja',
      sort_by: 'popularity.desc',
    });
    return enrichWithGenres(data.results, 'anime');
  }
  const data = await tmdbFetch<TmdbListResponse>('/discover/tv', {
    page: String(page),
  }).catch(() => null);
  if (data) return enrichWithGenres(data.results, 'anime');
  return fetchPopularTv(page);
}

export async function fetchNewReleases(page = 1): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const data = await tmdbFetch<TmdbListResponse>('/movie/now_playing', {
      page: String(page),
    });
    return enrichWithGenres(data.results, 'movie');
  }
  return fetchPopularMovies(page);
}

export async function fetchMediaDetails(
  id: string,
  type: MediaType,
): Promise<MediaItem | null> {
  if (hasTmdbKey()) {
    const tmdbType = mapTmdbType(type);
    const detail = await tmdbFetch<TmdbDetail>(`/${tmdbType}/${id}`, {
      append_to_response: 'credits',
    });
    const genres = detail.genres?.map((g) => g.name) ?? [];
    const cast: CastMember[] =
      detail.credits?.cast.slice(0, 12).map((c) => ({
        id: String(c.id),
        name: c.name,
        character: c.character,
        profilePath: c.profile_path ?? undefined,
      })) ?? [];
    const item = mapTmdbItem(detail, type, genres);
    item.cast = cast;
    item.runtime =
      detail.runtime ??
      detail.episode_run_time?.[0] ??
      undefined;
    item.imdbId = detail.imdb_id;
    return item;
  }

  const cinemetaType = type === 'movie' ? 'movie' : 'series';
  const imdbId = id.startsWith('tt') ? id : `tt${id}`;
  const meta = await cinemetaMeta(cinemetaType, imdbId);
  if (!meta) {
    const alt = await cinemetaMeta(cinemetaType, id);
    return alt ? mapCinemetaItem(alt, type) : null;
  }
  return mapCinemetaItem(meta, type);
}

export async function fetchSimilar(
  id: string,
  type: MediaType,
): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const tmdbType = mapTmdbType(type);
    const data = await tmdbFetch<TmdbListResponse>(`/${tmdbType}/${id}/similar`);
    return enrichWithGenres(data.results.slice(0, 12), type);
  }
  const detail = await fetchMediaDetails(id, type);
  if (!detail?.genres[0]) return fetchTrending(type);
  return fetchTrending(type).then((items) =>
    items.filter((i) => i.genres.includes(detail.genres[0])).slice(0, 12),
  );
}

export async function fetchRecommendations(
  id: string,
  type: MediaType,
): Promise<MediaItem[]> {
  if (hasTmdbKey()) {
    const tmdbType = mapTmdbType(type);
    const data = await tmdbFetch<TmdbListResponse>(
      `/${tmdbType}/${id}/recommendations`,
    );
    return enrichWithGenres(data.results.slice(0, 12), type);
  }
  return fetchSimilar(id, type);
}

export async function fetchHeroItems(): Promise<MediaItem[]> {
  const trending = await fetchTrending('movie', 1);
  return trending.slice(0, 5);
}

import type { MediaItem, SearchFilters } from '@/types/media';
import { hasTmdbKey, tmdbFetch } from './tmdb';
import { cinemetaSearch } from './cinemeta';

interface TmdbSearchResponse {
  results: {
    id: number;
    title?: string;
    name?: string;
    overview: string;
    poster_path: string | null;
    backdrop_path: string | null;
    vote_average: number;
    release_date?: string;
    first_air_date?: string;
    media_type?: string;
    genre_ids?: number[];
  }[];
}

function mapResult(
  item: TmdbSearchResponse['results'][0],
): MediaItem {
  const isTv = item.media_type === 'tv' || Boolean(item.name);
  return {
    id: String(item.id),
    tmdbId: item.id,
    title: item.title ?? item.name ?? 'Untitled',
    overview: item.overview ?? '',
    posterPath: item.poster_path ?? '',
    backdropPath: item.backdrop_path ?? '',
    mediaType: isTv ? 'tv' : 'movie',
    genres: [],
    cast: [],
    rating: item.vote_average ?? 0,
    releaseDate: item.release_date ?? item.first_air_date,
    year: Number((item.release_date ?? item.first_air_date ?? '').slice(0, 4)) || undefined,
  };
}

function mapCinemeta(
  meta: Awaited<ReturnType<typeof cinemetaSearch>>[0],
): MediaItem {
  return {
    id: meta.id,
    imdbId: meta.id.startsWith('tt') ? meta.id : undefined,
    title: meta.name,
    overview: meta.description ?? '',
    posterPath: meta.poster ?? '',
    backdropPath: meta.background ?? '',
    mediaType: meta.type === 'series' ? 'tv' : 'movie',
    genres: meta.genre ?? [],
    cast: [],
    rating: Number(meta.imdbRating) || 0,
    year: Number(meta.releaseInfo?.slice(0, 4)) || undefined,
  };
}

function applyFilters(items: MediaItem[], filters: SearchFilters): MediaItem[] {
  return items.filter((item) => {
    if (filters.type === 'movie' && item.mediaType !== 'movie') return false;
    if (filters.type === 'tv' && item.mediaType !== 'tv' && item.mediaType !== 'anime')
      return false;
    if (filters.genre && !item.genres.some((g) => g.toLowerCase() === filters.genre.toLowerCase()))
      return false;
    if (filters.year && String(item.year) !== filters.year) return false;
    if (filters.minRating > 0 && item.rating < filters.minRating) return false;
    return true;
  });
}

export async function searchMedia(
  query: string,
  filters: SearchFilters,
): Promise<MediaItem[]> {
  const q = query.trim();
  if (!q) return [];

  let results: MediaItem[] = [];

  if (hasTmdbKey()) {
    const data = await tmdbFetch<TmdbSearchResponse>('/search/multi', {
      query: q,
      include_adult: 'false',
    });
    results = data.results
      .filter((r) => r.media_type === 'movie' || r.media_type === 'tv')
      .map(mapResult);
  } else {
    const [movies, series] = await Promise.all([
      cinemetaSearch(q, 'movie'),
      cinemetaSearch(q, 'series'),
    ]);
    results = [...movies, ...series].map(mapCinemeta);
  }

  return applyFilters(results, filters);
}

export async function fetchSearchSuggestions(query: string): Promise<MediaItem[]> {
  const results = await searchMedia(query, {
    type: 'all',
    genre: '',
    year: '',
    minRating: 0,
  });
  return results.slice(0, 6);
}

