import { create } from 'zustand';
import type {
  ContinueWatchingItem,
  MediaItem,
  PlaybackSettings,
  WatchHistoryEntry,
} from '@/types/media';
import { readStorage, writeStorage, STORAGE_KEYS } from '@/utils/storage';

interface LibraryState {
  favorites: MediaItem[];
  history: WatchHistoryEntry[];
  continueWatching: ContinueWatchingItem[];
  playback: PlaybackSettings;
  toggleFavorite: (item: MediaItem) => void;
  isFavorite: (id: string) => boolean;
  addHistory: (item: MediaItem, progress?: number) => void;
  updateContinueWatching: (
    item: MediaItem,
    progress: number,
    duration: number,
  ) => void;
  removeContinueWatching: (id: string) => void;
  setPlaybackSettings: (settings: Partial<PlaybackSettings>) => void;
  clearHistory: () => void;
}

const defaultPlayback: PlaybackSettings = {
  preferredProviderId: 'primary',
  volume: 1,
  autoplay: true,
  subtitles: 'en',
};

function persist<K extends keyof typeof STORAGE_KEYS>(
  key: K,
  value: unknown,
): void {
  writeStorage(STORAGE_KEYS[key], value);
}

export const useLibraryStore = create<LibraryState>((set, get) => ({
  favorites: readStorage<MediaItem[]>(STORAGE_KEYS.favorites, []),
  history: readStorage<WatchHistoryEntry[]>(STORAGE_KEYS.history, []),
  continueWatching: readStorage<ContinueWatchingItem[]>(
    STORAGE_KEYS.continueWatching,
    [],
  ),
  playback: readStorage<PlaybackSettings>(STORAGE_KEYS.playback, defaultPlayback),

  toggleFavorite: (item) => {
    set((state) => {
      const exists = state.favorites.some((f) => f.id === item.id);
      const favorites = exists
        ? state.favorites.filter((f) => f.id !== item.id)
        : [...state.favorites, item];
      persist('favorites', favorites);
      return { favorites };
    });
  },

  isFavorite: (id) => get().favorites.some((f) => f.id === id),

  addHistory: (item, progress = 0) => {
    set((state) => {
      const entry: WatchHistoryEntry = {
        media: item,
        watchedAt: Date.now(),
        progress,
      };
      const history = [
        entry,
        ...state.history.filter((h) => h.media.id !== item.id),
      ].slice(0, 50);
      persist('history', history);
      return { history };
    });
  },

  updateContinueWatching: (item, progress, duration) => {
    set((state) => {
      const entry: ContinueWatchingItem = {
        media: item,
        progress,
        duration,
        updatedAt: Date.now(),
      };
      const continueWatching = [
        entry,
        ...state.continueWatching.filter((c) => c.media.id !== item.id),
      ].slice(0, 12);
      persist('continueWatching', continueWatching);
      return { continueWatching };
    });
  },

  removeContinueWatching: (id) => {
    set((state) => {
      const continueWatching = state.continueWatching.filter(
        (c) => c.media.id !== id,
      );
      persist('continueWatching', continueWatching);
      return { continueWatching };
    });
  },

  setPlaybackSettings: (settings) => {
    set((state) => {
      const playback = { ...state.playback, ...settings };
      persist('playback', playback);
      return { playback };
    });
  },

  clearHistory: () => {
    persist('history', []);
    set({ history: [] });
  },
}));

import { useEffect, useState } from 'react';

export function useDebounce<T>(value: T, delay = 400): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debounced;
}

import { useCallback, useEffect, useRef } from 'react';

interface UseInfiniteScrollOptions {
  enabled?: boolean;
  rootMargin?: string;
  onLoadMore: () => void;
}

export function useInfiniteScroll({
  enabled = true,
  rootMargin = '200px',
  onLoadMore,
}: UseInfiniteScrollOptions) {
  const sentinelRef = useRef<HTMLDivElement | null>(null);
  const loadingRef = useRef(false);

  const stableLoadMore = useCallback(() => {
    if (loadingRef.current) return;
    loadingRef.current = true;
    onLoadMore();
    requestAnimationFrame(() => {
      loadingRef.current = false;
    });
  }, [onLoadMore]);

  useEffect(() => {
    if (!enabled) return;
    const node = sentinelRef.current;
    if (!node) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          stableLoadMore();
        }
      },
      { rootMargin },
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, [enabled, rootMargin, stableLoadMore]);

  return sentinelRef;
}

import { useEffect } from 'react';

interface ShortcutMap {
  [key: string]: () => void;
}

export function useKeyboardShortcuts(shortcuts: ShortcutMap, enabled = true) {
  useEffect(() => {
    if (!enabled) return;

    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable
      ) {
        return;
      }

      const key = [
        e.ctrlKey || e.metaKey ? 'ctrl+' : '',
        e.shiftKey ? 'shift+' : '',
        e.key.toLowerCase(),
      ].join('');

      const action = shortcuts[key] ?? shortcuts[e.key.toLowerCase()];
      if (action) {
        e.preventDefault();
        action();
      }
    };

    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [shortcuts, enabled]);
}

import { useEffect, useState } from 'react';

export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(() =>
    typeof window !== 'undefined' ? window.matchMedia(query).matches : false,
  );

  useEffect(() => {
    const mq = window.matchMedia(query);
    const handler = (e: MediaQueryListEvent) => setMatches(e.matches);
    setMatches(mq.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [query]);

  return matches;
}

import { Component, type ErrorInfo, type ReactNode } from 'react';
import { Link } from 'react-router-dom';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false };

  static getDerivedStateFromError(): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('StreamForge error:', error, info);
  }

  render() {
    if (this.state.hasError) {
      return (
        this.fallback ?? (
          <motion-root className="flex min-h-[50vh] flex-col items-center justify-center gap-4 px-6 text-center">
            <h2 className="text-2xl font-semibold text-forge-glow">
              Something went wrong
            </h2>
            <p className="max-w-md text-sm text-white/60">
              We hit an unexpected error. Try refreshing or head back home.
            </p>
            <Link
              to="/"
              className="rounded-full border border-forge-green/40 bg-forge-green/10 px-6 py-2 text-sm font-medium text-forge-glow shadow-glow-sm transition hover:bg-forge-green/20"
            >
              Back to Home
            </Link>
          </motion-root>
        )
      );
    }
    return this.props.children;
  }
}

