import { useEffect, useState } from 'react';
import { Seo } from '@/components/ui/Seo';
import { HeroCarousel } from '@/components/media/HeroCarousel';
import { MediaRow } from '@/components/media/MediaRow';
import {
  fetchAnime,
  fetchHeroItems,
  fetchNewReleases,
  fetchPopularMovies,
  fetchPopularTv,
  fetchRecommendations,
  fetchTrending,
} from '@/services/media';
import type { MediaItem } from '@/types/media';
import { useLibraryStore } from '@/store/useLibraryStore';

export function HomePage() {
  const continueWatching = useLibraryStore((s) => s.continueWatching);
  const [hero, setHero] = useState<MediaItem[]>([]);
  const [trending, setTrending] = useState<MediaItem[]>([]);
  const [movies, setMovies] = useState<MediaItem[]>([]);
  const [tv, setTv] = useState<MediaItem[]>([]);
  const [anime, setAnime] = useState<MediaItem[]>([]);
  const [newReleases, setNewReleases] = useState<MediaItem[]>([]);
  const [recommendations, setRecommendations] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [heroItems, trend, popMovies, popTv, animeList, releases] =
          await Promise.all([
            fetchHeroItems(),
            fetchTrending('movie'),
            fetchPopularMovies(),
            fetchPopularTv(),
            fetchAnime(),
            fetchNewReleases(),
          ]);
        if (cancelled) return;
        setHero(heroItems);
        setTrending(trend);
        setMovies(popMovies);
        setTv(popTv);
        setAnime(animeList);
        setNewReleases(releases);
        const recSource = heroItems[0] ?? trend[0];
        if (recSource) {
          const recs = await fetchRecommendations(recSource.id, recSource.mediaType);
          if (!cancelled) setRecommendations(recs);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const progressMap = Object.fromEntries(
    continueWatching.map((c) => [
      c.media.id,
      (c.progress / Math.max(c.duration, 1)) * 100,
    ]),
  );

  return (
    <>
      <Seo />
      <HeroCarousel items={hero} loading={loading} />
      {continueWatching.length > 0 && (
        <MediaRow
          title="Continue Watching"
          items={continueWatching.map((c) => c.media)}
          progressMap={progressMap}
        />
      )}
      <MediaRow title="Trending Now" items={trending} loading={loading} />
      <MediaRow title="Popular Movies" items={movies} loading={loading} />
      <MediaRow title="TV Series" items={tv} loading={loading} />
      <MediaRow title="Anime" items={anime} loading={loading} />
      <MediaRow title="New Releases" items={newReleases} loading={loading} />
      <MediaRow title="Recommended For You" items={recommendations} loading={loading} />
    </>
  );
}

import { useEffect, useState } from 'react';
import { Seo } from '@/components/ui/Seo';
import { MediaCard } from '@/components/media/MediaCard';
import { PageLoader } from '@/components/ui/PageLoader';
import { useDebounce } from '@/hooks/useDebounce';
import { useInfiniteScroll } from '@/hooks/useInfiniteScroll';
import { fetchSearchSuggestions, GENRE_OPTIONS, searchMedia } from '@/services/search';
import type { MediaItem, SearchFilters } from '@/types/media';

const defaultFilters: SearchFilters = {
  type: 'all',
  genre: '',
  year: '',
  minRating: 0,
};

export function SearchPage() {
  const [query, setQuery] = useState('');
  const [filters, setFilters] = useState<SearchFilters>(defaultFilters);
  const [results, setResults] = useState<MediaItem[]>([]);
  const [suggestions, setSuggestions] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const debouncedQuery = useDebounce(query, 400);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setSuggestions([]);
      return;
    }
    fetchSearchSuggestions(debouncedQuery).then(setSuggestions);
  }, [debouncedQuery]);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }
    setLoading(true);
    setPage(1);
    searchMedia(debouncedQuery, filters).then((items) => {
      setResults(items);
      setLoading(false);
    });
  }, [debouncedQuery, filters]);

  const loadMore = () => setPage((p) => p + 1);
  const sentinelRef = useInfiniteScroll({
    enabled: results.length >= page * 20,
    onLoadMore: loadMore,
  });

  const visible = results.slice(0, page * 20);

  return (
    <>
      <Seo title="Search" description="Search movies, TV shows, and anime on StreamForge." />
      <motion.div className="mx-auto max-w-7xl px-4 py-6 sm:px-6">
        <h1 className="mb-6 text-2xl font-bold">Search</h1>
        <input
          type="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search movies, TV, anime…"
          className="w-full rounded-xl border border-white/10 bg-white/5 px-4 py-3 text-sm outline-none ring-forge-green/30 focus:border-forge-green/50 focus:ring-2"
        />

        {suggestions.length > 0 && query && (
          <motion.ul className="mt-2 overflow-hidden rounded-xl border border-white/10 bg-forge-dark/95">
            {suggestions.map((s) => (
              <li key={s.id}>
                <button
                  type="button"
                  className="w-full px-4 py-2 text-left text-sm hover:bg-forge-green/10"
                  onClick={() => setQuery(s.title)}
                >
                  {s.title}
                </button>
              </li>
            ))}
          </motion.ul>
        )}

        <motion.div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-5">
          <select
            value={filters.type}
            onChange={(e) =>
              setFilters((f) => ({ ...f, type: e.target.value as SearchFilters['type'] }))
            }
            className="rounded-lg border border-white/10 bg-black px-3 py-2 text-sm"
          >
            <option value="all">All types</option>
            <option value="movie">Movies</option>
            <option value="tv">TV</option>
          </select>
          <select
            value={filters.genre}
            onChange={(e) => setFilters((f) => ({ ...f, genre: e.target.value }))}
            className="rounded-lg border border-white/10 bg-black px-3 py-2 text-sm"
          >
            <option value="">All genres</option>
            {GENRE_OPTIONS.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
          <input
            type="number"
            placeholder="Year"
            value={filters.year}
            onChange={(e) => setFilters((f) => ({ ...f, year: e.target.value }))}
            className="rounded-lg border border-white/10 bg-black px-3 py-2 text-sm"
          />
          <select
            value={filters.minRating}
            onChange={(e) =>
              setFilters((f) => ({ ...f, minRating: Number(e.target.value) }))
            }
            className="rounded-lg border border-white/10 bg-black px-3 py-2 text-sm"
          >
            <option value={0}>Any rating</option>
            <option value={6}>6+</option>
            <option value={7}>7+</option>
            <option value={8}>8+</option>
          </select>
        </motion.div>

        {loading ? (
          <PageLoader />
        ) : (
          <motion.div className="mt-8 grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
            {visible.map((item) => (
              <MediaCard key={`${item.mediaType}-${item.id}`} item={item} />
            ))}
          </motion.div>
        )}
        <motion.div ref={sentinelRef} className="h-8" />
      </motion.div>
    </>
  );
}

import { useEffect, useState } from 'react';
import { Link, useParams, useSearchParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Seo } from '@/components/ui/Seo';
import { Button } from '@/components/ui/Button';
import { MediaRow } from '@/components/media/MediaRow';
import { PageLoader } from '@/components/ui/PageLoader';
import {
  fetchMediaDetails,
  fetchRecommendations,
  fetchSimilar,
} from '@/services/media';
import type { MediaItem, MediaType } from '@/types/media';
import { useLibraryStore } from '@/store/useLibraryStore';
import { backdropImage, posterImage } from '@/utils/images';
import { formatRating, formatRuntime, formatYear } from '@/utils/format';

export function DetailsPage() {
  const { id } = useParams<{ id: string }>();
  const [searchParams] = useSearchParams();
  const type = (searchParams.get('type') as MediaType) || 'movie';
  const [media, setMedia] = useState<MediaItem | null>(null);
  const [similar, setSimilar] = useState<MediaItem[]>([]);
  const [recommendations, setRecommendations] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(true);
  const toggleFavorite = useLibraryStore((s) => s.toggleFavorite);
  const isFavorite = useLibraryStore((s) => s.isFavorite);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    (async () => {
      setLoading(true);
      const detail = await fetchMediaDetails(id, type);
      if (cancelled || !detail) {
        setLoading(false);
        return;
      }
      setMedia(detail);
      const [sim, rec] = await Promise.all([
        fetchSimilar(id, type),
        fetchRecommendations(id, type),
      ]);
      if (!cancelled) {
        setSimilar(sim);
        setRecommendations(rec);
        setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [id, type]);

  if (loading) return <PageLoader />;
  if (!media) {
    return (
      <p className="px-6 py-20 text-center text-white/60">Title not found.</p>
    );
  }

  const fav = isFavorite(media.id);

  return (
    <>
      <Seo
        title={media.title}
        description={media.overview}
        image={posterImage(media.posterPath)}
      />
      <section className="relative">
        <motion.img
          src={backdropImage(media.backdropPath)}
          alt=""
          className="h-[45vh] w-full object-cover opacity-50"
        />
        <motion.div className="absolute inset-0 bg-gradient-to-t from-black via-black/60 to-transparent" />
        <motion.div className="relative mx-auto flex max-w-7xl flex-col gap-6 px-4 pb-10 sm:flex-row sm:px-6">
          <img
            src={posterImage(media.posterPath)}
            alt={media.title}
            className="mx-auto w-48 shrink-0 rounded-xl border border-forge-green/30 shadow-glow sm:mx-0 sm:w-56"
          />
          <motion.div className="flex-1">
            <h1 className="text-3xl font-bold sm:text-4xl">{media.title}</h1>
            <p className="mt-2 flex flex-wrap gap-3 text-sm text-white/60">
              <span>★ {formatRating(media.rating)}</span>
              <span>{formatYear(media.releaseDate, media.year)}</span>
              <span>{formatRuntime(media.runtime)}</span>
            </p>
            <motion.div className="mt-3 flex flex-wrap gap-2">
              {media.genres.map((g) => (
                <span
                  key={g}
                  className="rounded-full border border-forge-green/30 bg-forge-green/10 px-3 py-0.5 text-xs text-forge-glow"
                >
                  {g}
                </span>
              ))}
            </motion.div>
            <p className="mt-4 max-w-3xl text-sm leading-relaxed text-white/75">
              {media.overview}
            </p>
            {media.cast.length > 0 && (
              <motion.div className="mt-6">
                <h3 className="mb-2 text-sm font-semibold uppercase tracking-wide text-forge-glow">
                  Cast
                </h3>
                <p className="text-sm text-white/70">
                  {media.cast.map((c) => c.name).join(' · ')}
                </p>
              </motion.div>
            )}
            <motion.div className="mt-8 flex flex-wrap gap-3">
              <Link to={`/watch/${media.id}?type=${media.mediaType}`}>
                <Button className="text-base px-8 py-3">▶ Watch Now</Button>
              </Link>
              <Button
                variant="outline"
                onClick={() => toggleFavorite(media)}
              >
                {fav ? '★ Favorited' : '☆ Add to Favorites'}
              </Button>
            </motion.div>
          </motion.div>
        </motion.div>
      </section>
      <MediaRow title="Similar" items={similar} />
      <MediaRow title="More Like This" items={recommendations} />
    </>
  );
}

