import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Seo } from '@/components/ui/Seo';
import { PageLoader } from '@/components/ui/PageLoader';
import { SearchInput } from '@/components/search/SearchInput';
import { SearchResultCard } from '@/components/media/SearchResultCard';
import { MediaCard } from '@/components/media/MediaCard';
import { GenreBar } from '@/components/media/GenreBar';
import { useDebounce } from '@/hooks/useDebounce';
import { useInfiniteScroll } from '@/hooks/useInfiniteScroll';
import {
  fetchSearchSuggestions,
  searchMediaPaginated,
  TRENDING_QUERIES,
} from '@/services/search';
import { fetchPopularMovies, fetchPopularTv, fetchTrending } from '@/services/media';
import type { MediaItem, SearchFilters } from '@/types/media';
import {
  addRecentSearch,
  clearRecentSearches,
  getRecentSearches,
} from '@/utils/searchHistory';
import { SectionHeader } from '@/components/ui/SectionHeader';

const TYPE_TABS: { id: SearchFilters['type']; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'movie', label: 'Movies' },
  { id: 'tv', label: 'TV Shows' },
  { id: 'anime', label: 'Anime' },
];

const RATING_CHIPS = [
  { value: 0, label: 'Any rating' },
  { value: 6, label: '6+' },
  { value: 7, label: '7+' },
  { value: 8, label: '8+' },
];

function parseFilters(params: URLSearchParams): SearchFilters {
  return {
    type: (params.get('type') as SearchFilters['type']) || 'all',
    genre: params.get('genre') ?? '',
    year: params.get('year') ?? '',
    minRating: Number(params.get('rating') ?? 0),
  };
}

export function SearchPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const initialQ = searchParams.get('q') ?? '';
  const [query, setQuery] = useState(initialQ);
  const [filters, setFilters] = useState<SearchFilters>(() =>
    parseFilters(searchParams),
  );
  const [results, setResults] = useState<MediaItem[]>([]);
  const [suggestions, setSuggestions] = useState<MediaItem[]>([]);
  const [browse, setBrowse] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [totalResults, setTotalResults] = useState(0);
  const [recent, setRecent] = useState(getRecentSearches);
  const [focused, setFocused] = useState(false);

  const debouncedQuery = useDebounce(query, 350);
  const hasQuery = debouncedQuery.trim().length > 0;
  const hasGenreBrowse = !hasQuery && Boolean(filters.genre);

  const syncUrl = useCallback(
    (q: string, f: SearchFilters) => {
      const next = new URLSearchParams();
      if (q.trim()) next.set('q', q.trim());
      if (f.type !== 'all') next.set('type', f.type);
      if (f.genre) next.set('genre', f.genre);
      if (f.year) next.set('year', f.year);
      if (f.minRating > 0) next.set('rating', String(f.minRating));
      setSearchParams(next, { replace: true });
    },
    [setSearchParams],
  );

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setSuggestions([]);
      return;
    }
    fetchSearchSuggestions(debouncedQuery).then(setSuggestions);
  }, [debouncedQuery]);

  const runSearch = useCallback(
    async (pageNum: number, append: boolean) => {
      if (!hasQuery && !hasGenreBrowse) {
        setResults([]);
        setTotalPages(0);
        setTotalResults(0);
        return;
      }

      if (append) setLoadingMore(true);
      else setLoading(true);

      try {
        const data = await searchMediaPaginated(
          debouncedQuery,
          filters,
          pageNum,
        );
        setResults((prev) =>
          append ? [...prev, ...data.results] : data.results,
        );
        setPage(data.page);
        setTotalPages(data.totalPages);
        setTotalResults(data.totalResults);
        if (debouncedQuery.trim() && pageNum === 1) {
          addRecentSearch(debouncedQuery);
          setRecent(getRecentSearches());
        }
      } finally {
        setLoading(false);
        setLoadingMore(false);
      }
    },
    [debouncedQuery, filters, hasQuery, hasGenreBrowse],
  );

  useEffect(() => {
    syncUrl(debouncedQuery, filters);
    setPage(1);
    runSearch(1, false);
  }, [debouncedQuery, filters, syncUrl, runSearch]);

  useEffect(() => {
    if (hasQuery || hasGenreBrowse) return;
    Promise.all([
      fetchTrending('movie'),
      fetchPopularMovies(),
      fetchPopularTv(),
    ]).then(([trend, movies, tv]) => {
      setBrowse([...trend.slice(0, 8), ...movies.slice(0, 6), ...tv.slice(0, 6)]);
    });
  }, [hasQuery, hasGenreBrowse]);

  const loadMore = useCallback(() => {
    if (loadingMore || page >= totalPages) return;
    runSearch(page + 1, true);
  }, [loadingMore, page, totalPages, runSearch]);

  const sentinelRef = useInfiniteScroll({
    enabled: hasQuery && page < totalPages,
    onLoadMore: loadMore,
  });

  const showSuggestions = focused && hasQuery && suggestions.length > 0;

  const resultTitle = useMemo(() => {
    if (hasQuery) return `${totalResults} results for “${debouncedQuery}”`;
    if (hasGenreBrowse) return `${filters.genre} picks`;
    return '';
  }, [hasQuery, hasGenreBrowse, totalResults, debouncedQuery, filters.genre]);

  const commitSearch = () => {
    setFocused(false);
    syncUrl(query, filters);
    runSearch(1, false);
  };

  return (
    <>
      <Seo title="Search" description="Find movies, TV shows and anime on StreamForge." />

      <div className="sticky top-[57px] z-40 border-b border-white/[0.06] bg-surface-base/95 px-4 py-4 backdrop-blur-xl sm:px-6 lg:px-8">
        <SearchInput
          value={query}
          onChange={setQuery}
          onSubmit={commitSearch}
          suggestions={suggestions}
          showSuggestions={showSuggestions}
          onSelectSuggestion={(item) => {
            setQuery(item.title);
            setFocused(false);
          }}
          autoFocus
          size="lg"
        />

        <div className="mt-4 flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {TYPE_TABS.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setFilters((f) => ({ ...f, type: tab.id }))}
              className={`chip ${filters.type === tab.id ? 'chip-active' : ''}`}
            >
              {tab.label}
            </button>
          ))}
        </motion.div>

        <div className="mt-3 flex flex-wrap items-center gap-2">
          <input
            type="number"
            placeholder="Year"
            value={filters.year}
            onChange={(e) =>
              setFilters((f) => ({ ...f, year: e.target.value }))
            }
            className="w-24 rounded-full border border-white/10 bg-surface-raised px-3 py-2 text-sm outline-none focus:border-accent/40"
          />
          {RATING_CHIPS.map((chip) => (
            <button
              key={chip.value}
              type="button"
              onClick={() =>
                setFilters((f) => ({ ...f, minRating: chip.value }))
              }
              className={`chip text-xs ${filters.minRating === chip.value ? 'chip-active' : ''}`}
            >
              {chip.label}
            </button>
          ))}
          {(filters.year || filters.minRating > 0 || filters.genre) && (
            <button
              type="button"
              onClick={() =>
                setFilters({
                  type: filters.type,
                  genre: '',
                  year: '',
                  minRating: 0,
                })
              }
              className="text-xs text-accent-bright hover:underline"
            >
              Clear filters
            </button>
          )}
        </motion.div>
      </motion.div>

      <div className="mx-auto max-w-4xl px-4 py-6 sm:px-6 lg:px-8">
        {!hasQuery && !hasGenreBrowse && (
          <>
            {recent.length > 0 && (
              <section className="mb-8">
                <motion.div className="mb-3 flex items-center justify-between">
                  <h2 className="text-sm font-semibold text-white/70">
                    Recent searches
                  </h2>
                  <button
                    type="button"
                    onClick={() => {
                      clearRecentSearches();
                      setRecent([]);
                    }}
                    className="text-xs text-white/40 hover:text-accent-bright"
                  >
                    Clear
                  </button>
                </motion.div>
                <div className="flex flex-wrap gap-2">
                  {recent.map((term) => (
                    <button
                      key={term}
                      type="button"
                      onClick={() => setQuery(term)}
                      className="chip text-sm"
                    >
                      {term}
                    </button>
                  ))}
                </motion.div>
              </section>
            )}

            <section className="mb-8">
              <h2 className="section-label mb-3">Trending searches</h2>
              <div className="flex flex-wrap gap-2">
                {TRENDING_QUERIES.map((term) => (
                  <button
                    key={term}
                    type="button"
                    onClick={() => setQuery(term)}
                    className="chip hover:border-accent/40 hover:text-accent-bright"
                  >
                    {term}
                  </button>
                ))}
              </motion.div>
            </section>

            <GenreBar />

            {browse.length > 0 && (
              <section>
                <SectionHeader label="Discover" title="Popular right now" />
                <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
                  {browse.map((item) => (
                    <MediaCard key={`${item.mediaType}-${item.id}`} item={item} variant="grid" />
                  ))}
                </motion.div>
              </section>
            )}
          </>
        )}

        {(hasQuery || hasGenreBrowse) && (
          <>
            {resultTitle && (
              <p className="mb-4 text-sm text-white/50">{resultTitle}</p>
            )}
            {loading ? (
              <PageLoader />
            ) : results.length === 0 ? (
              <div className="glass-panel py-16 text-center">
                <p className="text-lg font-semibold text-white">No results found</p>
                <p className="mt-2 text-sm text-white/50">
                  Try a different title, loosen filters, or browse genres below.
                </p>
              </motion.div>
            ) : (
              <ul className="space-y-3">
                {results.map((item, i) => (
                  <li key={`${item.mediaType}-${item.id}-${i}`}>
                    <SearchResultCard item={item} index={i} />
                  </li>
                ))}
              </ul>
            )}
            {loadingMore && (
              <p className="py-6 text-center text-sm text-white/40">Loading more…</p>
            )}
            <div ref={sentinelRef} className="h-10" />
          </>
        )}
      </motion.div>
    </>
  );
}

import { useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { MediaItem } from '@/types/media';
import { posterImage } from '@/utils/images';
import { formatRating, formatYear } from '@/utils/format';

interface SearchInputProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: () => void;
  suggestions: MediaItem[];
  showSuggestions: boolean;
  onSelectSuggestion: (item: MediaItem) => void;
  onFocusChange?: (focused: boolean) => void;
  autoFocus?: boolean;
  size?: 'md' | 'lg';
}

export function SearchInput({
  value,
  onChange,
  onSubmit,
  suggestions,
  showSuggestions,
  onSelectSuggestion,
  onFocusChange,
  autoFocus,
  size = 'md',
}: SearchInputProps) {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (autoFocus) inputRef.current?.focus();
  }, [autoFocus]);

  return (
    <motion.div className="relative">
      <span className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-white/35">
        <svg
          className="h-5 w-5"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          aria-hidden
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
          />
        </svg>
      </span>
      <input
        ref={inputRef}
        type="search"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onFocus={() => onFocusChange?.(true)}
        onBlur={() => setTimeout(() => onFocusChange?.(false), 150)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') onSubmit();
          if (e.key === 'Escape') onChange('');
        }}
        placeholder="Search movies, TV shows, anime…"
        className={`input-search ${size === 'lg' ? 'py-4 text-lg' : ''}`}
        autoComplete="off"
      />
      {value && (
        <button
          type="button"
          onClick={() => onChange('')}
          className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full px-2 py-1 text-xs text-white/40 hover:bg-white/10 hover:text-white"
        >
          Clear
        </button>
      )}

      <AnimatePresence>
        {showSuggestions && suggestions.length > 0 && (
          <motion.ul
            initial={{ opacity: 0, y: -4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -4 }}
            className="absolute left-0 right-0 top-[calc(100%+8px)] z-50 max-h-[min(420px,60vh)] overflow-y-auto rounded-2xl border border-white/10 bg-surface-raised/98 p-2 shadow-card backdrop-blur-xl"
          >
            {suggestions.map((item) => (
              <li key={`${item.mediaType}-${item.id}`}>
                <button
                  type="button"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => onSelectSuggestion(item)}
                  className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition hover:bg-accent-muted"
                >
                  <img
                    src={posterImage(item.posterPath, 'w342')}
                    alt=""
                    className="h-14 w-10 rounded-md object-cover"
                  />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate font-medium text-white">
                      {item.title}
                    </span>
                    <span className="text-xs text-white/45">
                      ★ {formatRating(item.rating)}
                      <span className="meta-dot" />
                      {formatYear(item.releaseDate, item.year)}
                    </span>
                  </span>
                </button>
              </li>
            ))}
            <li className="border-t border-white/5 px-3 py-2">
              <button
                type="button"
                onMouseDown={(e) => e.preventDefault()}
                onClick={onSubmit}
                className="w-full text-center text-sm font-medium text-accent-bright hover:underline"
              >
                See all results for &quot;{value}&quot;
              </button>
            </li>
          </motion.ul>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Seo } from '@/components/ui/Seo';
import { PageLoader } from '@/components/ui/PageLoader';
import { SearchInput } from '@/components/search/SearchInput';
import { SearchResultCard } from '@/components/media/SearchResultCard';
import { MediaCard } from '@/components/media/MediaCard';
import { GenreBar } from '@/components/media/GenreBar';
import { useDebounce } from '@/hooks/useDebounce';
import { useInfiniteScroll } from '@/hooks/useInfiniteScroll';
import {
  fetchSearchSuggestions,
  searchMediaPaginated,
  TRENDING_QUERIES,
} from '@/services/search';
import { fetchPopularMovies, fetchPopularTv, fetchTrending } from '@/services/media';
import type { MediaItem, SearchFilters } from '@/types/media';
import {
  addRecentSearch,
  clearRecentSearches,
  getRecentSearches,
} from '@/utils/searchHistory';
import { SectionHeader } from '@/components/ui/SectionHeader';

const TYPE_TABS: { id: SearchFilters['type']; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'movie', label: 'Movies' },
  { id: 'tv', label: 'TV Shows' },
  { id: 'anime', label: 'Anime' },
];

const RATING_CHIPS = [
  { value: 0, label: 'Any rating' },
  { value: 6, label: '6+' },
  { value: 7, label: '7+' },
  { value: 8, label: '8+' },
];

function parseFilters(params: URLSearchParams): SearchFilters {
  return {
    type: (params.get('type') as SearchFilters['type']) || 'all',
    genre: params.get('genre') ?? '',
    year: params.get('year') ?? '',
    minRating: Number(params.get('rating') ?? 0),
  };
}

export function SearchPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [query, setQuery] = useState(() => searchParams.get('q') ?? '');
  const [filters, setFilters] = useState<SearchFilters>(() =>
    parseFilters(searchParams),
  );
  const [results, setResults] = useState<MediaItem[]>([]);
  const [suggestions, setSuggestions] = useState<MediaItem[]>([]);
  const [browse, setBrowse] = useState<MediaItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [totalResults, setTotalResults] = useState(0);
  const [recent, setRecent] = useState(getRecentSearches);
  const [focused, setFocused] = useState(false);

  const debouncedQuery = useDebounce(query, 350);
  const hasQuery = debouncedQuery.trim().length > 0;
  const hasGenreBrowse = !hasQuery && Boolean(filters.genre);

  const syncUrl = useCallback(
    (q: string, f: SearchFilters) => {
      const next = new URLSearchParams();
      if (q.trim()) next.set('q', q.trim());
      if (f.type !== 'all') next.set('type', f.type);
      if (f.genre) next.set('genre', f.genre);
      if (f.year) next.set('year', f.year);
      if (f.minRating > 0) next.set('rating', String(f.minRating));
      setSearchParams(next, { replace: true });
    },
    [setSearchParams],
  );

  useEffect(() => {
    const q = searchParams.get('q') ?? '';
    setQuery(q);
    setFilters(parseFilters(searchParams));
  }, [searchParams]);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setSuggestions([]);
      return;
    }
    fetchSearchSuggestions(debouncedQuery).then(setSuggestions);
  }, [debouncedQuery]);

  useEffect(() => {
    let cancelled = false;

    async function load(pageNum: number, append: boolean) {
      if (!hasQuery && !hasGenreBrowse) {
        setResults([]);
        setTotalPages(0);
        setTotalResults(0);
        return;
      }

      if (append) setLoadingMore(true);
      else setLoading(true);

      try {
        const data = await searchMediaPaginated(
          debouncedQuery,
          filters,
          pageNum,
        );
        if (cancelled) return;
        setResults((prev) =>
          append ? [...prev, ...data.results] : data.results,
        );
        setPage(data.page);
        setTotalPages(data.totalPages);
        setTotalResults(data.totalResults);
        if (debouncedQuery.trim() && pageNum === 1) {
          addRecentSearch(debouncedQuery);
          setRecent(getRecentSearches());
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
          setLoadingMore(false);
        }
      }
    }

    syncUrl(debouncedQuery, filters);
    load(1, false);

    return () => {
      cancelled = true;
    };
  }, [debouncedQuery, filters, hasQuery, hasGenreBrowse, syncUrl]);

  useEffect(() => {
    if (hasQuery || hasGenreBrowse) return;
    Promise.all([
      fetchTrending('movie'),
      fetchPopularMovies(),
      fetchPopularTv(),
    ]).then(([trend, movies, tv]) => {
      setBrowse([...trend.slice(0, 8), ...movies.slice(0, 6), ...tv.slice(0, 6)]);
    });
  }, [hasQuery, hasGenreBrowse]);

  const loadMore = useCallback(() => {
    if (loadingMore || page >= totalPages) return;
    setLoadingMore(true);
    searchMediaPaginated(debouncedQuery, filters, page + 1).then((data) => {
      setResults((prev) => [...prev, ...data.results]);
      setPage(data.page);
      setLoadingMore(false);
    });
  }, [loadingMore, page, totalPages, debouncedQuery, filters]);

  const sentinelRef = useInfiniteScroll({
    enabled: (hasQuery || hasGenreBrowse) && page < totalPages,
    onLoadMore: loadMore,
  });

  const showSuggestions = focused && hasQuery && suggestions.length > 0;

  const resultTitle = useMemo(() => {
    if (hasQuery) return `${totalResults} results for “${debouncedQuery}”`;
    if (hasGenreBrowse) return `Top ${filters.genre} titles`;
    return '';
  }, [hasQuery, hasGenreBrowse, totalResults, debouncedQuery, filters.genre]);

  const commitSearch = () => {
    setFocused(false);
    syncUrl(query, filters);
  };

  return (
    <>
      <Seo title="Search" description="Find movies, TV shows and anime on StreamForge." />

      <header className="sticky top-[57px] z-40 border-b border-white/[0.06] bg-surface-base/95 px-4 py-4 backdrop-blur-xl sm:px-6 lg:px-8">
        <SearchInput
          value={query}
          onChange={setQuery}
          onSubmit={commitSearch}
          suggestions={suggestions}
          showSuggestions={showSuggestions}
          onFocusChange={setFocused}
          onSelectSuggestion={(item) => {
            setQuery(item.title);
            setFocused(false);
          }}
          autoFocus
          size="lg"
        />

        <div className="mt-4 flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {TYPE_TABS.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setFilters((f) => ({ ...f, type: tab.id }))}
              className={`chip ${filters.type === tab.id ? 'chip-active' : ''}`}
            >
              {tab.label}
            </button>
          ))}
        </header>

        <motion.div className="mt-3 flex flex-wrap items-center gap-2">
          <input
            type="number"
            placeholder="Year"
            value={filters.year}
            onChange={(e) =>
              setFilters((f) => ({ ...f, year: e.target.value }))
            }
            className="w-24 rounded-full border border-white/10 bg-surface-raised px-3 py-2 text-sm outline-none focus:border-accent/40"
          />
          {RATING_CHIPS.map((chip) => (
            <button
              key={chip.value}
              type="button"
              onClick={() =>
                setFilters((f) => ({ ...f, minRating: chip.value }))
              }
              className={`chip text-xs ${filters.minRating === chip.value ? 'chip-active' : ''}`}
            >
              {chip.label}
            </button>
          ))}
          {(filters.year || filters.minRating > 0) && (
            <button
              type="button"
              onClick={() =>
                setFilters((f) => ({
                  ...f,
                  year: '',
                  minRating: 0,
                }))
              }
              className="text-xs text-accent-bright hover:underline"
            >
              Clear filters
            </button>
          )}
        </motion.div>
      </header>

      <main className="mx-auto max-w-4xl px-4 py-6 sm:px-6 lg:px-8">
        {!hasQuery && !hasGenreBrowse && (
          <>
            {recent.length > 0 && (
              <section className="mb-8">
                <motion.div className="mb-3 flex items-center justify-between">
                  <h2 className="text-sm font-semibold text-white/70">
                    Recent searches
                  </h2>
                  <button
                    type="button"
                    onClick={() => {
                      clearRecentSearches();
                      setRecent([]);
                    }}
                    className="text-xs text-white/40 hover:text-accent-bright"
                  >
                    Clear
                  </button>
                </motion.div>
                <motion.div className="flex flex-wrap gap-2">
                  {recent.map((term) => (
                    <button
                      key={term}
                      type="button"
                      onClick={() => setQuery(term)}
                      className="chip text-sm"
                    >
                      {term}
                    </button>
                  ))}
                </motion.div>
              </section>
            )}

            <section className="mb-8">
              <h2 className="section-label mb-3">Trending searches</h2>
              <motion.div className="flex flex-wrap gap-2">
                {TRENDING_QUERIES.map((term) => (
                  <button
                    key={term}
                    type="button"
                    onClick={() => setQuery(term)}
                    className="chip hover:border-accent/40 hover:text-accent-bright"
                  >
                    {term}
                  </button>
                ))}
              </motion.div>
            </section>

            <GenreBar />

            {browse.length > 0 && (
              <section>
                <SectionHeader label="Discover" title="Popular right now" />
                <motion.div className="grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
                  {browse.map((item) => (
                    <MediaCard
                      key={`${item.mediaType}-${item.id}`}
                      item={item}
                      variant="grid"
                    />
                  ))}
                </motion.div>
              </section>
            )}
          </>
        )}

        {(hasQuery || hasGenreBrowse) && (
          <>
            {resultTitle && (
              <p className="mb-4 text-sm text-white/50">{resultTitle}</p>
            )}
            {loading ? (
              <PageLoader />
            ) : results.length === 0 ? (
              <motion.div className="glass-panel py-16 text-center">
                <p className="text-lg font-semibold text-white">No results found</p>
                <p className="mt-2 text-sm text-white/50">
                  Try a different title, loosen filters, or browse genres below.
                </p>
              </motion.div>
            ) : (
              <ul className="space-y-3">
                {results.map((item, i) => (
                  <li key={`${item.mediaType}-${item.id}-${i}`}>
                    <SearchResultCard item={item} index={i} />
                  </li>
                ))}
              </ul>
            )}
            {loadingMore && (
              <p className="py-6 text-center text-sm text-white/40">Loading more…</p>
            )}
            <div ref={sentinelRef} className="h-10" />
          </>
        )}
      </main>
    </>
  );
}

