    <nav className="fixed bottom-0 left-0 right-0 z-50 border-t border-white/[0.08] bg-surface-base/95 px-2 py-2 backdrop-blur-xl md:hidden">
      <ul className="flex justify-around">
        {items.map((item) => (
          <li key={item.to}>
            <NavLink
