];

/** Prefer live TMDB logo paths over stale hardcoded paths */
export function mergeProviderLogos(
  featured: WatchProvider[],
  fromApi: WatchProvider[],
): WatchProvider[] {
  const apiById = new Map(fromApi.map((p) => [p.id, p]));
  return featured.map((p) => {
    const live = apiById.get(p.id);
    return {
      ...p,
      name: live?.name ?? p.name,
      logoPath: live?.logoPath || p.logoPath,
      brandColor: p.brandColor ?? live?.brandColor,
    };
  });
}

